import torch,copy,functools
class ControlNet(torch.nn.Module):
    def __init__(self, base):
        super().__init__(); self.net = base(width_mult=0.25)
    def forward(self,x,t): return self.net(x,t)

def solve_alpha_beta(eps, g_phi, g_bar, l2=1e-6):
    # closed-form ridge (per-batch, scalar weights)
    A = torch.stack([g_phi.flatten(1), g_bar.flatten(1)],-1)  # B×D×2
    y = eps.flatten(1)                                        # B×D
    ATA = A.transpose(1,2)@A + l2*torch.eye(2,device=A.device)
    ATy = A.transpose(1,2)@y
    w = torch.linalg.solve(ATA.mean(0), ATy.mean(0))          # 2-vector
    return w[0],w[1]

class MLCVDiff(torch.nn.Module):
    def __init__(self,unet):
        super().__init__(); self.score=unet(); self.ctrl=ControlNet(unet)
    def forward(self,x_t,t,eps):
        with torch.no_grad():
            g_phi = self.ctrl(x_t,t);
            g_bar = analytic_cv(eps,t)  # pre-computed table
            alpha,beta = solve_alpha_beta(eps,g_phi,g_bar)
            delta = eps - alpha*g_phi - beta*g_bar
        pred = self.score(x_t,t)
        loss = ((delta - (pred - alpha*g_phi - beta*g_bar))**2).mean()
        return loss
